export function findStudentByQuery(query: string): RealStudentData | undefined {
  const q = query.trim().toLowerCase();
  return REAL_STUDENTS_BATCH_2025_2029.find(
    (s) =>
      s.vmNo === q ||
      `vm${s.vmNo}`.toLowerCase() === q ||
      s.regNo.toLowerCase() === q ||
      s.email.toLowerCase() === q ||
      s.name.toLowerCase().includes(q)
  );
}

export function getStudentsBySection(section: "A" | "B" | "C"): RealStudentData[] {
  return REAL_STUDENTS_BATCH_2025_2029.filter((s) => s.section === section);
}

export function getStudentsByMentor(mentorName: string): RealStudentData[] {
  return REAL_STUDENTS_BATCH_2025_2029.filter((s) =>
    s.mentorName.toLowerCase().includes(mentorName.toLowerCase())
  );
}
